// PV7 (PV-47): moving a library's files between managed storage and a customer bucket, over the real router, the
// real storage-worker handler and s3rver. The migration runner is driven with retrying steps, as Workflows would.
// Generated bytes only.

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { randomBytes } from "node:crypto";
import { jest } from "@jest/globals";
import { clearRowCache, handle as storageHandle, type Env as StorageEnv } from "@storage-worker/index";
import { forgetStore } from "@media-worker/storage/stores";
import { COPY_PART_BYTES, copyObject, runMigration, type MigrationParams } from "@media-worker/storage/migrate";
import type { Step, StepConfig } from "@media-worker/pipeline/run";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

jest.setTimeout(90_000);
beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});

const step: Step = {
  async do<T>(_name: string, config: StepConfig, fn: () => Promise<T>): Promise<T> {
    const limit = config.retries?.limit ?? 0;
    for (let attempt = 0; ; attempt++) {
      try {
        return await fn();
      } catch (e) {
        if (attempt >= limit) throw e;
      }
    }
  },
};

describe("moving a library's files between stores", () => {
  let server: { run(): Promise<{ port: number }>; close(): Promise<void> };
  let dir: string;
  let endpoint: string;

  beforeAll(async () => {
    dir = mkdtempSync(join(tmpdir(), "pv-mig-"));
    const S3rver = (await import("s3rver")).default as unknown as new (o: Record<string, unknown>) => typeof server;
    server = new S3rver({ port: 0, address: "127.0.0.1", silent: true, directory: dir, configureBuckets: [{ name: "team-bucket" }, { name: "second-bucket" }] });
    endpoint = `http://127.0.0.1:${(await server.run()).port}`;
  });
  afterAll(async () => {
    await server?.close();
    rmSync(dir, { recursive: true, force: true });
  });

  let w: World;
  let owner: User, editor: User;
  let A: { id: string; pub: string; slug: string };
  let lib: { id: string; slug: string };
  let base: string;
  let runs: { id: string; params: MigrationParams }[];

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Shots" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    const sw: StorageEnv = { ENVIRONMENT: "test", PLATFORM_DB: w.env.PLATFORM_DB!, STORAGE_KEK: "e".repeat(64), ALLOW_TEST_ENDPOINTS: "true" };
    clearRowCache();
    forgetStore();
    w.env.STORAGE_WORKER = { fetch: (input: RequestInfo | URL, init?: RequestInit) => storageHandle(new Request(String(input), init), sw) } as unknown as Fetcher;
    runs = [];
    w.env.MIGRATE_STORAGE = { create: async (o: { id: string; params: MigrationParams }) => (runs.push(o), { id: o.id }) } as unknown as NonNullable<Env["MIGRATE_STORAGE"]>;
  });
  type Env = import("@media-worker/env").Env;

  const bucket = (name = "team-bucket", prefix = "px") => ({ endpoint, region: "us-east-1", bucket: name, prefix, pathStyle: true, accessKeyId: "S3RVER", secretAccessKey: "S3RVER" });

  async function upload(user: User, name: string, bytes: Uint8Array) {
    const created = await w.call(user, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream" });
    if (created.status !== 201) return created;
    const s = created.json.data.session;
    for (let n = 1; n <= s.partCount; n++) await w.put(user, `${base}/uploads/${s.id}/parts/${n}`, bytes.subarray((n - 1) * s.partSize, Math.min(n * s.partSize, bytes.length)));
    return w.call(user, "POST", `${base}/uploads/${s.id}/commit`);
  }
  const content = async (id: string) => Buffer.from((await w.bytes(editor, `${base}/files/${id}/content`)).bytes);
  const runAll = async () => {
    const out = [];
    for (const r of runs.splice(0)) out.push(await runMigration(w.env, r.params, step, () => w.now));
    return out;
  };

  it("managed → bucket → managed: every file moves, stays readable, and uploads wait while it runs", async () => {
    const files = [];
    for (let i = 0; i < 3; i++) {
      const bytes = randomBytes(700 + i);
      files.push({ bytes, id: (await upload(editor, `f${i}.bin`, bytes)).json.data.file.id });
    }
    const start = await w.call(owner, "POST", `${base}/storage/migrations`, { target: "bucket", ...bucket() });
    expect(start.status).toBe(202);
    expect(start.json.data.migration).toMatchObject({ state: "copying", total: 3 });
    expect(JSON.stringify(start.json)).not.toContain("S3RVER");

    // While it runs: reads still work (old store), uploads and purges wait, and the target isn't current yet.
    expect((await content(files[0]!.id)).equals(Buffer.from(files[0]!.bytes))).toBe(true);
    const blocked = await w.call(editor, "POST", `${base}/uploads`, { name: "late.bin", size: 5, sha256: sha256hex(randomBytes(5)), mime: "application/octet-stream" });
    expect(blocked.json.error.code).toBe("storage_changing");
    await w.call(owner, "DELETE", `${base}/files/${files[2]!.id}`);
    expect((await w.call(owner, "DELETE", `${base}/files/${files[2]!.id}?permanent=1`)).json.error.code).toBe("storage_changing");
    expect((await w.call(owner, "GET", `${base}/storage`)).json.data.current.kind).toBe("managed-r2");

    expect(await runAll()).toEqual(["done"]);
    const view = (await w.call(owner, "GET", `${base}/storage`)).json.data;
    expect(view.current).toMatchObject({ kind: "s3-compatible", bucket: "team-bucket", status: "active" });
    expect(view.migration).toMatchObject({ state: "done", copied: 3, missing: 0 });
    expect(JSON.parse(w.kv.get(`lib:${A.slug}/${lib.slug}`)!).b.p).toBe("px/");

    // Reads now come from the bucket: remove the managed copies to prove it (the product itself keeps them).
    w.bucket.objects.clear();
    forgetStore();
    for (const f of files.slice(0, 2)) expect((await content(f.id)).equals(Buffer.from(f.bytes))).toBe(true);
    const after = await upload(editor, "new.bin", randomBytes(400));
    expect(after.status).toBe(200);
    expect(w.bucket.objects.size).toBe(0);

    // And back to managed storage.
    const back = await w.call(owner, "POST", `${base}/storage/migrations`, { target: "managed" });
    expect(back.status).toBe(202);
    expect(await runAll()).toEqual(["done"]);
    expect((await w.call(owner, "GET", `${base}/storage`)).json.data.current.kind).toBe("managed-r2");
    expect(JSON.parse(w.kv.get(`lib:${A.slug}/${lib.slug}`)!).b).toBeUndefined();
    forgetStore();
    for (const f of files.slice(0, 2)) expect((await content(f.id)).equals(Buffer.from(f.bytes))).toBe(true);
    expect(w.bucket.objects.size).toBe(4); // f0, f1, the trashed f2 and new.bin
  });

  it("a failed copy leaves the library where it was, unlocked, and says why", async () => {
    const bytes = randomBytes(900);
    const file = (await upload(editor, "a.bin", bytes)).json.data.file;
    expect((await w.call(owner, "POST", `${base}/storage/migrations`, { target: "bucket", ...bucket() })).status).toBe(202);
    // the target bucket goes away after it was tested
    const target = runs[0]!.params.to;
    w.db.prepare(`UPDATE media_storage_backends SET bucket = 'gone-bucket' WHERE id = ?`).run(target);
    clearRowCache();
    expect(await runAll()).toEqual(["failed"]);
    const view = (await w.call(owner, "GET", `${base}/storage`)).json.data;
    expect(view.current.kind).toBe("managed-r2");
    expect(view.migration).toMatchObject({ state: "failed", error: "NoSuchBucket" });
    expect(view.history.find((b: { id: string }) => b.id.endsWith(target.replace(/-/g, "")))).toMatchObject({ status: "retired", lastError: "NoSuchBucket" });
    expect((await content(file.id)).equals(Buffer.from(bytes))).toBe(true);
    expect((await upload(editor, "b.bin", randomBytes(10))).status).toBe(200);
  });

  it("only managers start one; open uploads must finish first; one at a time", async () => {
    expect((await w.call(editor, "POST", `${base}/storage/migrations`, { target: "managed" })).status).toBe(404);
    expect((await w.call(owner, "POST", `${base}/storage/migrations`, { target: "managed" })).json.error.code).toBe("conflict");
    const open = await w.call(editor, "POST", `${base}/uploads`, { name: "o.bin", size: 5, sha256: sha256hex(randomBytes(5)), mime: "application/octet-stream" });
    expect(open.status).toBe(201);
    const r = await w.call(owner, "POST", `${base}/storage/migrations`, { target: "bucket", ...bucket() });
    expect(r.json.error).toMatchObject({ code: "uploads_open", details: { uploads: 1 } });
    await w.call(editor, "DELETE", `${base}/uploads/${open.json.data.session.id}`);
    expect((await w.call(owner, "POST", `${base}/storage/migrations`, { target: "bucket", ...bucket() })).status).toBe(202);
    expect((await w.call(owner, "POST", `${base}/storage/migrations`, { target: "bucket", ...bucket("second-bucket") })).json.error.code).toBe("storage_changing");
  });

  it("large objects are copied in parts and checked", async () => {
    const big = randomBytes(COPY_PART_BYTES + 3000);
    const sha = sha256hex(big);
    const src = new Map<string, Uint8Array>();
    src.set("k", big);
    const store = (m: Map<string, Uint8Array>) => ({
      async get(key: string, o?: { range?: { offset: number; length: number } }) {
        const b = m.get(key);
        if (!b) return null;
        const part = o?.range ? b.subarray(o.range.offset, o.range.offset + o.range.length) : b;
        return { body: new Response(part).body!, size: b.length, arrayBuffer: async () => Uint8Array.from(part).buffer };
      },
      async put(key: string, body: ArrayBuffer | ArrayBufferView | ReadableStream) {
        m.set(key, new Uint8Array(body as ArrayBuffer));
      },
      async delete(key: string) {
        m.delete(key);
      },
      async createMultipartUpload() {
        return { uploadId: "u1" };
      },
      resumeMultipartUpload(key: string) {
        const parts = new Map<number, Uint8Array>();
        return {
          async uploadPart(n: number, body: ArrayBuffer | ArrayBufferView | ReadableStream) {
            parts.set(n, new Uint8Array(body as ArrayBuffer));
            return { partNumber: n, etag: `e${n}` };
          },
          async complete(list: { partNumber: number }[]) {
            m.set(key, Buffer.concat(list.map((p) => parts.get(p.partNumber)!)));
          },
          async abort() {},
        };
      },
    });
    const dst = new Map<string, Uint8Array>();
    expect(await copyObject(store(src), store(dst), { object_key: "k", size: big.length, sha256: sha })).toBe("copied");
    expect(sha256hex(dst.get("k")!)).toBe(sha);
    // a target that silently drops the parts fails the read-back check
    await expect(copyObject(store(src), { ...store(new Map()), resumeMultipartUpload: () => ({ uploadPart: async (n: number) => ({ partNumber: n, etag: "x" }), complete: async () => undefined, abort: async () => undefined }) }, { object_key: "k", size: big.length, sha256: sha })).rejects.toThrow();
  });
});
